<h1>Dashboard</h1><div class="grid"><div class="card"><div class="muted">Closed trades</div><strong style="font-size:1.8rem"><?=e($summary['closed_count'])?></strong></div><div class="card"><div class="muted">Net P&amp;L</div><strong class="<?=((float)$summary['pnl']>=0?'positive':'negative')?>" style="font-size:1.8rem"><?=number_format((float)$summary['pnl'],2)?></strong></div><div class="card"><div class="muted">Accounts</div><strong style="font-size:1.8rem"><?=count($accounts)?></strong></div></div><div class="card"><h2>Accounts</h2><?php if(!$accounts):?><p class="muted">Create your first account.</p><?php else:?><div class="table-wrap"><table><tr><th>Account</th><th>Currency</th><th>Initial</th><th>P&amp;L</th><th>Current</th><th>Trades</th></tr><?php foreach($accounts as $a):$cur=(float)$a['initial_balance']+(float)$a['pnl'];?><tr><td><?=e($a['name'])?></td><td><?=e($a['currency'])?></td><td><?=number_format((float)$a['initial_balance'],2)?></td><td class="<?=((float)$a['pnl']>=0?'positive':'negative')?>"><?=number_format((float)$a['pnl'],2)?></td><td><?=number_format($cur,2)?></td><td><?=e($a['trade_count'])?></td></tr><?php endforeach;?></table></div><?php endif;?></div>
